{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "summary_heading",
        "summary_intro_text",
        "rec_1_card",
        "rec_2_card",
        "rec_3_card",
        "comparison_table_heading",
        "comparison_table",
        "top_pick_heading",
        "top_pick_card",
        "quick_actions_heading",
        "ts_tantan_menu_button",
        "shibuya_map_button",
        "sources_heading",
        "ts_tantan_source_button",
        "nagi_shokudo_source_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Shibuya Vegan Dining Comparison",
        "variant": "h1"
      },
      "children": []
    },
    "summary_heading": {
      "type": "Text",
      "props": {
        "text": "Restaurant Evaluation Summary",
        "variant": "h2"
      },
      "children": []
    },
    "summary_intro_text": {
      "type": "Text",
      "props": {
        "text": "Based on your group of 4 and a budget of under 5,000 JPY per person, here is the comparison of vegan-friendly options in Shibuya:",
        "variant": "body"
      },
      "children": []
    },
    "rec_1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "rec_1_title_stack",
        "rec_1_reason"
      ]
    },
    "rec_1_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "rec_1_name",
        "rec_1_status"
      ]
    },
    "rec_1_name": {
      "type": "Text",
      "props": {
        "text": "T's Tantan",
        "variant": "h3"
      },
      "children": []
    },
    "rec_1_status": {
      "type": "Text",
      "props": {
        "text": "Top Recommendation",
        "variant": "chip"
      },
      "children": []
    },
    "rec_1_reason": {
      "type": "Text",
      "props": {
        "text": "Perfectly fits the budget and offers zero travel time for those arriving via JR lines. The food is 100% vegan and consistently highly rated.",
        "variant": "body"
      },
      "children": []
    },
    "rec_2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "rec_2_title_stack",
        "rec_2_reason"
      ]
    },
    "rec_2_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "rec_2_name",
        "rec_2_status"
      ]
    },
    "rec_2_name": {
      "type": "Text",
      "props": {
        "text": "Nagi Shokudo",
        "variant": "h3"
      },
      "children": []
    },
    "rec_2_status": {
      "type": "Text",
      "props": {
        "text": "Excellent Alternative",
        "variant": "chip"
      },
      "children": []
    },
    "rec_2_reason": {
      "type": "Text",
      "props": {
        "text": "Offers a more relaxed cafe atmosphere with creative vegan sets. The 10-minute walk is manageable and the value is excellent.",
        "variant": "body"
      },
      "children": []
    },
    "rec_3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "rec_3_title_stack",
        "rec_3_reason"
      ]
    },
    "rec_3_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "rec_3_name",
        "rec_3_status"
      ]
    },
    "rec_3_name": {
      "type": "Text",
      "props": {
        "text": "Gonpachi Nishi-Azabu",
        "variant": "h3"
      },
      "children": []
    },
    "rec_3_status": {
      "type": "Text",
      "props": {
        "text": "Not Recommended",
        "variant": "chip"
      },
      "children": []
    },
    "rec_3_reason": {
      "type": "Text",
      "props": {
        "text": "Exceeds the budget for a full meal and requires an expensive taxi ride, making it the least efficient choice for your group.",
        "variant": "body"
      },
      "children": []
    },
    "comparison_table_heading": {
      "type": "Text",
      "props": {
        "text": "Comparison Table",
        "variant": "h2"
      },
      "children": []
    },
    "comparison_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "restaurant",
            "label": "Restaurant"
          },
          {
            "key": "price_range",
            "label": "Price Range"
          },
          {
            "key": "vegan_suitability",
            "label": "Vegan Suitability"
          },
          {
            "key": "station_proximity",
            "label": "Station Proximity"
          }
        ],
        "rows": [
          {
            "restaurant": "T's Tantan",
            "price_range": "1,000-1,500 JPY",
            "vegan_suitability": "100% Vegan",
            "station_proximity": "Inside JR Station"
          },
          {
            "restaurant": "Nagi Shokudo",
            "price_range": "1,200-2,000 JPY",
            "vegan_suitability": "100% Vegan",
            "station_proximity": "10-min walk"
          },
          {
            "restaurant": "Gonpachi",
            "price_range": "4,000-8,000 JPY",
            "vegan_suitability": "Mixed Menu",
            "station_proximity": "15-min taxi"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "top_pick_heading": {
      "type": "Text",
      "props": {
        "text": "Top Pick: T's Tantan (Shibuya Station)",
        "variant": "h2"
      },
      "children": []
    },
    "top_pick_card": {
      "type": "Card",
      "props": {},
      "children": [
        "top_pick_image",
        "top_pick_details_stack"
      ]
    },
    "top_pick_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Shinjuku_Station_South_Exit.jpg/1200px-Shinjuku_Station_South_Exit.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "top_pick_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "top_pick_best_for_stack",
        "top_pick_menu_stack",
        "top_pick_efficiency_stack"
      ]
    },
    "top_pick_best_for_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "top_pick_star_icon",
        "top_pick_best_for_text"
      ]
    },
    "top_pick_star_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/star.svg"
      },
      "children": []
    },
    "top_pick_best_for_text": {
      "type": "Text",
      "props": {
        "text": "Best for Groups: The most convenient and cost-effective option for a group of 4.",
        "variant": "body"
      },
      "children": []
    },
    "top_pick_menu_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "top_pick_menu_icon",
        "top_pick_menu_text"
      ]
    },
    "top_pick_menu_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/menu-button-wide.svg"
      },
      "children": []
    },
    "top_pick_menu_text": {
      "type": "Text",
      "props": {
        "text": "Menu: Famous for rich, creamy vegan ramen and gyoza that appeal to both vegans and meat-eaters alike.",
        "variant": "body"
      },
      "children": []
    },
    "top_pick_efficiency_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "top_pick_efficiency_icon",
        "top_pick_efficiency_text"
      ]
    },
    "top_pick_efficiency_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/clock.svg"
      },
      "children": []
    },
    "top_pick_efficiency_text": {
      "type": "Text",
      "props": {
        "text": "Efficiency: Located within the ticket gates of the JR station, it maximizes your time for exploring Shibuya.",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "ts_tantan_menu_button": {
      "type": "Button",
      "props": {
        "label": "View T's Tantan Menu"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ts-restaurant.jp/tantan/menu/"
          }
        }
      },
      "children": []
    },
    "shibuya_map_button": {
      "type": "Button",
      "props": {
        "label": "Open Shibuya Vegan Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/maps/search/vegan+restaurants+shibuya"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "ts_tantan_source_button": {
      "type": "Button",
      "props": {
        "label": "T's Tantan Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ts-restaurant.jp/tantan/"
          }
        }
      },
      "children": []
    },
    "nagi_shokudo_source_button": {
      "type": "Button",
      "props": {
        "label": "Nagi Shokudo Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://nagi-shokudo.com/"
          }
        }
      },
      "children": []
    }
  }
}
